import type { InputPluginOption } from "rollup";
import path from "path";
import {
  minify,
  uiPage,
  sass,
  seismic,
  json,
  swc,
  replace,
  commonjs,
  nodeResolve,
  url,
  header,
  sourcemapUrl,
  outputOptions,
  cssUrl,
} from "../index";
import type { RegisterExplicitIdFunction, Credential } from "./types";
// Note: devServerPlugins uses Node-only require() calls internally. It is only
// invoked when dev: true, which is a Node-only use case, so including it in
// the browser bundle is safe — it is never called in a browser context.
import { devServerPlugins } from "./dev-server-plugins";

interface ReactPluginsOptions {
  scope: string;
  rootDir: string;
  registerExplicitId?: RegisterExplicitIdFunction; // not called when dev: true
  dev?: boolean;
  enableCacheBusting?: boolean;
  // The following options only apply when dev: true
  watchPaths: string[];
  proxyPaths: string[];
  credential?: Credential;
  omitDevUxGlobals?: boolean;
}

/**
 * Creates an updateSrcPath function for transforming script source paths
 * @param config Configuration options
 * @returns Function that transforms original path and emitted filename to final source path
 */
export const createUpdateSrcPath = (config: {
  scope: string;
  preserveSrc: boolean;
  enableCacheBusting: boolean;
}) => {
  const { scope, preserveSrc, enableCacheBusting } = config;

  return (originalPath: string, emittedFileName: string): string => {
    if (preserveSrc) {
      return emittedFileName;
    }

    const ext = path.extname(emittedFileName);
    const outName = emittedFileName.substring(
      0,
      emittedFileName.length - ext.length,
    );

    const srcPath = `/uxasset/externals/${scope}/${outName}.jsdbx`;

    const url = new URL(originalPath, "http://dummy");
    const params = new URLSearchParams(url.search);

    if (!enableCacheBusting) {
      return params.size > 0 ? `${srcPath}?${params.toString()}` : srcPath;
    }

    const cacheBustingQueryParam = "uxpcb";
    const cacheBustingQueryParamWithJellyTemplate = `${cacheBustingQueryParam}=$[UxFrameworkScriptables.getFlushTimestamp()]`;

    // Remove any existing uxpcb parameter if it exists
    params.delete(cacheBustingQueryParam);

    // Handle separately to avoid encoding special characters needed for Jelly syntax
    const queryParamsString =
      params.size > 0
        ? `?${params.toString()}&${cacheBustingQueryParamWithJellyTemplate}`
        : `?${cacheBustingQueryParamWithJellyTemplate}`;

    return `${srcPath}${queryParamsString}`;
  };
};

// Sys ID of the @devsnc/library-uxf app on ServiceNow instances — provides the UXF theme
// in dev mode. This is a system-level package ID that is consistent across instances.
const LIBRARY_UXF_APP_SYS_ID = "c86a62e2c7022010099a308dc7c26022";

export default async ({
  scope,
  rootDir,
  registerExplicitId,
  dev = false,
  enableCacheBusting = true,
  watchPaths,
  proxyPaths,
  credential,
  omitDevUxGlobals = false,
}: ReactPluginsOptions): Promise<InputPluginOption[]> => {
  if (!dev && !registerExplicitId) {
    throw new Error("registerExplicitId is required when dev is false");
  }
  return [
    dev
      ? !omitDevUxGlobals &&
        header(`import "/uxasset/externals/@devsnc/library-uxf/index.jsdbx";
const themeLink = document.createElement('link');
themeLink.dataset.sourceId = 'glide-theme';
themeLink.rel = 'stylesheet';
themeLink.href = '/$uxappimmutables.do?sysparm_request_type=ux_theme&sysparm_app_sys_id=${LIBRARY_UXF_APP_SYS_ID}&uxpcb=${Date.now()}';
document.head.appendChild(themeLink);
document.querySelectorAll('*').forEach(el => {
  if (/^(?:g2?|j):/i.test(el.tagName)) {
    el.remove();
  }
});
`)
      : outputOptions((rawOptions) => {
          const fileNames = "[name].jsdbx";
          if (Array.isArray(rawOptions)) {
            for (const output of rawOptions) {
              output.entryFileNames = fileNames;
              output.chunkFileNames = fileNames;
            }
          } else {
            rawOptions.entryFileNames = fileNames;
            rawOptions.chunkFileNames = fileNames;
          }
          return rawOptions;
        }),
    uiPage({
      rootDir,
      serializerOptions: dev ? { selfClosingTags: false } : {},
      entryPath(entry: string, { fullPath }: { fullPath: string }) {
        const entryWithoutQueryParams = entry.replace(/\?.+/, "");
        const fullPathWithoutQueryParams = fullPath.replace(/\?.+/, "");
        const normalizedPath = path.normalize(
          entryWithoutQueryParams.replace(/^(?:\.\.\/)+/, ""),
        );
        const ext = path.extname(normalizedPath);
        const outName = normalizedPath.substring(
          0,
          normalizedPath.length - ext.length,
        );
        return {
          [`${outName}`]: fullPathWithoutQueryParams,
        };
      },
      updateSrcPath: createUpdateSrcPath({
        scope,
        preserveSrc: dev,
        enableCacheBusting,
      }),
    }),
    seismic(),
    replace({
      "process.env.NODE_ENV": "'production'",
      preventAssignment: true,
    }),
    url({
      sourceDir: rootDir,
      fileName: "[dirname][name][extname]",
      updateExport: (data: string) => {
        if (dev || data.startsWith("data:")) {
          return data;
        }
        return path.join(scope, data);
      },
    }),
    json(),
    cssUrl({
      shouldExtract: (_, fileContent, mimeType) => {
        if (mimeType.startsWith("image/") || mimeType.startsWith("font/")) {
          return fileContent.length > 14 * 1024;
        }
        return false;
      },
      getExtractNameAndUrl(url, filePath, mimeType) {
        const relativePath = path.relative(rootDir, filePath);
        if (dev) {
          return { name: relativePath, url: relativePath };
        }
        if (mimeType.startsWith("image/")) {
          return {
            name: relativePath,
            url: path.join(scope, relativePath),
          };
        }
        if (mimeType.startsWith("font/")) {
          const explicitId = registerExplicitId!(
            "sys_ux_theme_asset",
            relativePath,
          );
          return {
            name: relativePath,
            url: `/uxta/${explicitId}.assetx?path=${relativePath}`,
          };
        }
        throw Error(
          `Unexpected mime type ${mimeType} for extracted url ${url}`,
        );
      },
    }),
    sass({
      insert: true,
      shouldExtract(_, fileContent) {
        return fileContent.length > 14 * 1024;
      },
      getExtractNameAndUrl(filePath) {
        let relativeRoot = rootDir;
        for (
          let currentPath = filePath;
          path.dirname(currentPath) !== currentPath;
          currentPath = path.dirname(currentPath)
        ) {
          if (path.basename(currentPath) === "node_modules") {
            relativeRoot = path.dirname(currentPath);
            break;
          }
        }
        const relativePath = path.relative(relativeRoot, filePath);
        const ext = path.extname(relativePath);
        const relativePathWithoutExt = relativePath.substring(
          0,
          relativePath.length - ext.length,
        );
        const resultRelativePath = `${relativePathWithoutExt}.css`;
        if (dev) {
          return { name: resultRelativePath, url: resultRelativePath };
        }
        const explicitId = registerExplicitId!(
          "sys_ux_theme_asset",
          resultRelativePath,
        );
        return {
          name: resultRelativePath,
          url: `/uxta/${explicitId}.assetx?path=${relativePath}`,
        };
      },
    }),
    nodeResolve({
      preferBuiltins: false,
      browser: true,
      extensions: [
        ".cjs",
        ".mjs",
        ".js",
        ".json",
        ".node",
        ".jsx",
        ".ts",
        ".tsx",
      ],
    }),
    swc({
      swc: {
        jsc: {
          parser: {
            tsx: true,
            syntax: "typescript",
          },
          transform: {
            react: {
              runtime: "automatic",
            },
          },
          experimental: {
            // Required for seismic plugin: prevents SWC from stripping import attributes
            // (e.g., "with { external: 'uxasset' }") during transpilation, allowing the
            // seismic plugin's resolveId hook to access them via options.attributes
            // Note: Property is named 'keepImportAssertions' in SWC but handles both 'assert' and 'with' syntax
            keepImportAssertions: true,
          },
        },
      },
    }),
    commonjs(),
    minify({ compress: true, mangle: false }),
    // working around issue in UXF where assets ending in index are wrapped with a try-catch breaking import/exports
    // also provides a process global for libs that expect it
    header("/*__ESM_BODY_START__*/window.process={};"),
    dev
      ? await devServerPlugins({ watchPaths, proxyPaths, credential })
      : sourcemapUrl({
          replaceUrl: (url) => `${url.replace("dbx", "")}.jsdbx`,
        }),
  ];
};
